#!/usr/bin/env bash
# Lua-first, conservative Hyprland entrypoint guard.
# Repairs ONLY a missing entry or Hyprland's known autogenerated Lua sample.
# Never overwrites a custom Lua configuration or an unexpected symlink.
set -euo pipefail

script_path="$(readlink -f -- "${BASH_SOURCE[0]}")"
script_dir="$(cd -- "$(dirname -- "$script_path")" && pwd)"
repo_root="$(cd -- "$script_dir/../.." && pwd)"
target="${1:-$HOME/.config/hypr/hyprland.lua}"
source_entry="$repo_root/common/hyprland.lua"
source_modules="$repo_root/common/lua"

[[ -f "$source_entry" && -d "$source_modules" ]] || {
  echo "Managed Lua source modules missing; refusing repair" >&2
  exit 1
}

# Explicit .conf audit remains supported for legacy tooling, but 0.57 uses Lua.
if [[ "$target" == *.conf ]]; then
  grep -qxF 'source = $RepoRoot/common/hyprland.conf' "$target" 2>/dev/null ||
    { echo "Legacy .conf wrapper differs from expected; no change made" >&2; exit 1; }
  echo "Legacy .conf wrapper intact (not the active 0.57 config)"
  exit 0
fi

# Validate the modules symlink, too. Don't hide a broken deployment by fixing
# the entrypoint alone.
modules="$(dirname -- "$target")/lua"
if [[ -L "$modules" && "$(readlink -f -- "$modules")" == "$source_modules" ]]; then
  :
else
  echo "Lua module link missing or incorrect: $modules" >&2
  echo "Run set-hypr-profile.sh --dry-run first; do not auto-delete paths." >&2
  exit 1
fi

if [[ -L "$target" ]]; then
  if [[ "$(readlink -f -- "$target")" == "$source_entry" ]]; then
    echo "Managed Lua entrypoint intact: $target"
    exit 0
  fi
  echo "Unexpected Lua symlink target; refusing overwrite: $target" >&2
  exit 1
fi

if [[ -e "$target" ]]; then
  if ! grep -q 'AUTOGENERATED HYPRLAND CONFIG' "$target" 2>/dev/null; then
    echo "Unexpected custom Lua entrypoint; refusing overwrite: $target" >&2
    exit 1
  fi
  backup="$target.autogenerated.$(date +%Y%m%d%H%M%S)"
  cp -a -- "$target" "$backup"
  rm -- "$target"
  echo "Backed up autogenerated sample to $backup"
fi

ln -s "$source_entry" "$target"
echo "Restored Lua entrypoint link: $target"
